WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_pos1__", "mixed Case" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") SELECT MIN("id") AS "id", MAX("id") AS "__ggsql_max_id", MIN("val") AS "val", MAX("val") AS "__ggsql_max_val", MIN("grp") AS "grp", MAX("grp") AS "__ggsql_max_grp", MIN("day") AS "day", MAX("day") AS "__ggsql_max_day", MIN("mixed Case") AS "mixed Case", MAX("mixed Case") AS "__ggsql_max_mixed Case" FROM "__ggsql_source__";
