SELECT * FROM (SELECT * FROM ggsql_live_test) AS "__schema__" LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "id" AS "__ggsql_aes_pos1__", "val" AS "__ggsql_aes_pos2__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") SELECT MIN("id") AS "id", MAX("id") AS "__ggsql_max_id", MIN("val") AS "val", MAX("val") AS "__ggsql_max_val", MIN("grp") AS "grp", MAX("grp") AS "__ggsql_max_grp", MIN("day") AS "day", MAX("day") AS "__ggsql_max_day", MIN("mixed Case") AS "mixed Case", MAX("mixed Case") AS "__ggsql_max_mixed Case" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_pos1" AS "__ggsql_aes_pos1__", "__ggsql_stat_intensity" AS "__ggsql_aes_pos2__" FROM (WITH coefficients AS ( SELECT "__ggsql_aes_stroke__", AVG("__ggsql_aes_pos1__") AS x_mean, AVG("__ggsql_aes_pos2__") AS y_mean, AVG("__ggsql_aes_pos1__" * "__ggsql_aes_pos2__") AS xy_mean, AVG("__ggsql_aes_pos1__" * "__ggsql_aes_pos1__") AS xx_mean, MIN("__ggsql_aes_pos1__") AS x_min, MAX("__ggsql_aes_pos1__") AS x_max FROM (SELECT *, "id" AS "__ggsql_aes_pos1__", "val" AS "__ggsql_aes_pos2__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_smooth__" WHERE "__ggsql_aes_pos1__" IS NOT NULL AND "__ggsql_aes_pos2__" IS NOT NULL GROUP BY "__ggsql_aes_stroke__" ) SELECT "__ggsql_aes_stroke__", x_min AS "__ggsql_stat_pos1", (y_mean + ((xy_mean - x_mean * y_mean) / (xx_mean - x_mean * x_mean)) * (x_min - x_mean)) AS "__ggsql_stat_intensity" FROM coefficients UNION ALL SELECT "__ggsql_aes_stroke__", x_max AS "__ggsql_stat_pos1", (y_mean + ((xy_mean - x_mean * y_mean) / (xx_mean - x_mean * x_mean)) * (x_max - x_mean)) AS "__ggsql_stat_intensity" FROM coefficients) AS "__ggsql_stat__";

