WITH "__ggsql_source__" AS (SELECT *, "id" AS "__ggsql_aes_pos1__", "val" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") SELECT MIN("id") AS "id", MAX("id") AS "__ggsql_max_id", MIN("val") AS "val", MAX("val") AS "__ggsql_max_val", MIN("grp") AS "grp", MAX("grp") AS "__ggsql_max_grp", MIN("day") AS "day", MAX("day") AS "__ggsql_max_day", MIN("mixed Case") AS "mixed Case", MAX("mixed Case") AS "__ggsql_max_mixed Case" FROM "__ggsql_source__";
SELECT proj4text FROM spatial_ref_sys WHERE srid = 4326 LIMIT 1;
SELECT ST_Transform(ST_SetSRID(ST_Point(0, 0), 4326), '+proj=merc +lon_0=0') AS g;
DROP TABLE IF EXISTS "__ggsql_clip_boundary_<session>__";
CREATE TEMP TABLE "__ggsql_clip_boundary_<session>__" AS SELECT ST_Transform(ST_SetSRID(ST_GeomFromText('POLYGON((-180.000000 85.000000, 180.000000 85.000000, 180.000000 -85.000000, -180.000000 -85.000000, -180.000000 85.000000))'), 4326), '+proj=longlat +datum=WGS84 +no_defs +type=crs') AS geom;
SELECT ST_AsText(ST_Transform(ST_SetSRID(ST_GeomFromText('POLYGON((-180.000000 85.000000, 180.000000 85.000000, 180.000000 -85.000000, -180.000000 -85.000000, -180.000000 85.000000))'), 4326), '+proj=merc +lon_0=0')) AS wkt;
SELECT MIN(ST_XMIN(g)) AS xmin, MIN(ST_YMIN(g)) AS ymin, MAX(ST_XMAX(g)) AS xmax, MAX(ST_YMAX(g)) AS ymax FROM (SELECT ST_ENVELOPE(ST_Transform(ST_SetSRID(geom, 4326), '+proj=merc +lon_0=0')) AS g FROM __ggsql_clip_boundary_<session>__);
DROP TABLE IF EXISTS "__ggsql_layer_0___proj";
CREATE TEMP TABLE "__ggsql_layer_0___proj" AS SELECT ST_X("__ggsql_proj_pt__") AS "__ggsql_aes_pos1__", ST_Y("__ggsql_proj_pt__") AS "__ggsql_aes_pos2__" FROM (SELECT *, ST_Transform(ST_SetSRID(ST_Point("__ggsql_aes_pos1__", "__ggsql_aes_pos2__"), 4326), '+proj=merc +lon_0=0') AS "__ggsql_proj_pt__" FROM (SELECT *, "id" AS "__ggsql_aes_pos1__", "val" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_proj__") AS "__ggsql_pp__";
SELECT MIN("__ggsql_aes_pos1__"), MIN("__ggsql_aes_pos2__"), MAX("__ggsql_aes_pos1__"), MAX("__ggsql_aes_pos2__") FROM "__ggsql_layer_0___proj";
SELECT * FROM "__ggsql_layer_0___proj";

-- case: text_date_cast
SELECT * FROM (SELECT * FROM ggsql_live_test) AS "__schema__" LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "day" AS "__ggsql_aes_pos1__", "val" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") SELECT MIN("id") AS "id", MAX("id") AS "__ggsql_max_id", MIN("val") AS "val", MAX("val") AS "__ggsql_max_val", MIN("grp") AS "grp", MAX("grp") AS "__ggsql_max_grp", MIN("day") AS "day", MAX("day") AS "__ggsql_max_day", MIN("mixed Case") AS "mixed Case", MAX("mixed Case") AS "__ggsql_max_mixed Case" FROM "__ggsql_source__";
SELECT *, "day" AS "__ggsql_aes_pos1__", "val" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__";

